const first = $input.first();
const j = first.json || {};
const text = (j.chatInput || '').toString();
const bin = first.binary || {};
const sources = [];
if (text.trim()) sources.push({ name: 'chat', text: text });
for (const k of Object.keys(bin)) {
  const buf = await this.helpers.getBinaryDataBuffer(0, k);
  sources.push({ name: bin[k].fileName || k, text: buf.toString('utf8') });
}
function clean(t){ return t.replace(/\r/g,'').replace(/[ \t]+\n/g,'\n').replace(/\n{3,}/g,'\n\n').trim(); }
const chunks = [];
for (const s of sources) {
  const body = clean(s.text);
  const parts = body.split(/^=== ?TRANSCRIPT.*$/m).map(clean).filter(Boolean);
  const list = parts.length ? parts : [body];
  list.forEach(function(p, idx){
    const meeting = (p.match(/^Meeting:\s*(.+)$/mi) || [])[1] || null;
    const date = (p.match(/^Date:\s*(.+)$/mi) || [])[1] || null;
    const attendees = (p.match(/^Attendees:\s*(.+)$/mi) || [])[1] || null;
    const speakers = Array.from(new Set((p.match(/^[A-Z][A-Za-z .'-]{1,30}(?=:\s)/gm) || []).filter(function(x){ return !/^(Meeting|Date|Attendees)$/i.test(x); })));
    chunks.push({ file: s.name, index: idx + 1, meeting: meeting, date: date, attendees: attendees, speakers: speakers, text: p });
  });
}
const normalized = chunks.map(function(c){ return '### SOURCE: ' + c.file + ' (part ' + c.index + ')\n' + c.text; }).join('\n\n');
return [{ json: { sources: sources, chunks: chunks, fileCount: Object.keys(bin).length, userText: text, normalized_text: normalized } }];

const j = $input.first().json;
const t = j.normalized_text || '';
const compare = j.fileCount >= 2 || /\bcompare\b/i.test(j.userText || '');
const speakerLines = (t.match(/^[A-Z][A-Za-z .'-]{1,30}:\s+\S/gm) || []).length;
let type = 'notes';
if (/^Attendees:/mi.test(t) || speakerLines >= 3) type = 'transcript';
else if (/Product Brief/i.test(t) || /KEY REQUIREMENTS/i.test(t)) type = 'brief';
else if (/Interview/i.test(t) || /^\s*[-*\u2022]\s+/m.test(t)) type = 'notes';
return [{ json: Object.assign({}, j, { route: compare ? 'compare' : 'main', input_type: type }) }];

function parseJson(raw){ var t=(raw||'').toString().replace(/^\s*```(?:json)?\s*/i,'').replace(/```\s*$/,'').trim(); return JSON.parse(t); }
const src = $('C2 Input Router').first().json;
const raw = ($json.output || '').toString();
let ex = null; let parseError = null;
try { ex = parseJson(raw); } catch (e) { parseError = 'Extractor did not return valid JSON: ' + e.message; }
if (!ex || typeof ex !== 'object') ex = {};
['stated_requirements','acceptance_criteria','ambiguous_items','contradictions','stakeholders','deadlines','dependencies','missing_info'].forEach(function(k){ if (!Array.isArray(ex[k])) ex[k] = []; });
if (typeof ex.input_status !== 'string') ex.input_status = ex.stated_requirements.length ? 'OK' : 'INSUFFICIENT';
if (parseError) ex.input_status = 'INSUFFICIENT';
const norm = function(s){ return (s || '').toString().replace(/\s+/g, ' ').trim(); };
const hay = norm(src.normalized_text);
const flags = [];
ex.stated_requirements.forEach(function(r, i){
  if (!r.id) r.id = 'R' + (i + 1);
  const q = norm(r.source_quote);
  r.quote_verified = q.length > 0 && hay.indexOf(q) !== -1;
  if (!r.quote_verified) flags.push(r.id + ': source_quote not found verbatim in source');
  (Array.isArray(r.verbatim_values) ? r.verbatim_values : []).forEach(function(v){
    if (hay.indexOf(norm(v)) === -1) flags.push(r.id + ': value "' + v + '" not found verbatim in source');
  });
});
ex.acceptance_criteria.forEach(function(a){
  if (hay.indexOf(norm(a.text)) === -1 && hay.indexOf(norm(a.source_quote)) === -1) flags.push('AC for ' + a.for + ': text not verbatim in source');
});
const count = ex.stated_requirements.length;
const L = [];
L.push('GATE 1 - Requirements review (input type: ' + src.input_type + ')');
L.push('');
L.push('Stated requirements (' + count + '):');
ex.stated_requirements.forEach(function(r){ L.push('- ' + r.id + ' [' + (r.type || '?') + '] ' + r.text + '  <<' + r.source_quote + '>>' + (r.quote_verified ? '' : '  [RED FLAG: unverified]')); });
if (ex.acceptance_criteria.length) { L.push(''); L.push('Acceptance criteria:'); ex.acceptance_criteria.forEach(function(a){ L.push('- (' + a.for + ') ' + a.text); }); }
if (ex.ambiguous_items.length) { L.push(''); L.push('Ambiguous items:'); ex.ambiguous_items.forEach(function(a){ L.push('- ' + a.text + ' - ' + a.why); }); }
if (ex.contradictions.length) { L.push(''); L.push('Contradictions (unresolved):'); ex.contradictions.forEach(function(c){ L.push('- ' + c.a + '  VS  ' + c.b + (c.said_by ? ' (' + c.said_by + ')' : '')); }); }
if (ex.stakeholders.length) { L.push(''); L.push('Stakeholders:'); ex.stakeholders.forEach(function(s){ L.push('- ' + s.name + (s.role ? ' (' + s.role + ')' : '') + ': ' + s.viewpoint); }); }
if (ex.deadlines.length) { L.push(''); L.push('Deadlines: ' + ex.deadlines.map(function(d){ return d.text; }).join('; ')); }
if (ex.dependencies.length) { L.push('Dependencies: ' + ex.dependencies.map(function(d){ return d.text; }).join('; ')); }
if (ex.missing_info.length) { L.push('Missing info: ' + ex.missing_info.join('; ')); }
if (flags.length) { L.push(''); L.push('C4 red flags:'); flags.forEach(function(f){ L.push('- ' + f); }); }
L.push('');
L.push('Reply "approve" to continue, or reply with your edits / deletions / answers (they will be applied as approved requirements notes).');
return [{ json: { extraction: ex, flags: flags, count: count, status: ex.input_status, parse_error: parseError, gate1_message: L.join('\n'), a1_done_at: Date.now() } }];

