function parseJson(raw){ var t=(raw||'').toString().replace(/^\s*```(?:json)?\s*/i,'').replace(/```\s*$/,'').trim(); return JSON.parse(t); }
const ORDER = ['Product Overview','Goals and Objectives','User Personas','Feature Requirements','Acceptance Criteria','Out of Scope','Dependencies','Assumptions','Open Questions','Timeline'];
let prd = null; let err = null;
try { const p = parseJson($json.output); prd = p.prd || p; } catch (e) { err = 'PRD Generator returned invalid JSON: ' + e.message; }
if (!prd || typeof prd !== 'object') prd = {};
const keys = Object.keys(prd);
const missing = ORDER.filter(function(k){ return keys.indexOf(k) === -1; });
const present = keys.filter(function(k){ return ORDER.indexOf(k) !== -1; });
const inOrder = present.join('|') === ORDER.filter(function(k){ return present.indexOf(k) !== -1; }).join('|');
const fr = (prd['Feature Requirements'] || {});
const rows = [].concat(Array.isArray(fr.functional) ? fr.functional : [], Array.isArray(fr.non_functional) ? fr.non_functional : []);
const noSource = rows.filter(function(r){ return !r.source; }).map(function(r){ return r.id || r.requirement; });
const ordered = {};
ORDER.forEach(function(k){ ordered[k] = prd[k] !== undefined ? prd[k] : 'Not stated in source - see Open Questions'; });
return [{ json: { prd: ordered, compliance: { ok: !err && missing.length === 0 && inOrder && noSource.length === 0, missing_sections: missing, in_order: inOrder, rows_without_source: noSource, parse_error: err } } }];

