function pj(raw) {
  try {
    var t = String(raw || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
    return JSON.parse(t);
  } catch (e) { return null; }
}
const full = $('A5 Scope Estimator').isExecuted;
const tc = $('Evaluation Trigger').first().json;
const ei = $('Eval Input').first().json;
const c2 = $('C2 Input Router').first().json;
const c4 = $('C4 Verify and Validate').first().json;
let gaps; let est = null; let prd = null; let compliance = null; let epics = []; let stories = []; let approved = null; let a3Done = null;
if (full) {
  const st = $('Parse Stories').first().json;
  const a4raw = $('A4 Gap Analyzer (full)').first().json.output;
  const a5raw = $('A5 Scope Estimator').first().json.output;
  gaps = pj(a4raw) || { parse_error: 'A4 output was not valid JSON', raw: String(a4raw || '').slice(0, 4000) };
  est = pj(a5raw) || { estimates: [], parse_error: 'A5 output was not valid JSON', raw: String(a5raw || '').slice(0, 4000) };
  approved = $('Apply Gate 1 Decision').first().json.approved_requirements;
  prd = st.prd; compliance = st.compliance; epics = st.epics || []; stories = st.stories || [];
  a3Done = Number(st.a3_done_at) || null;
} else {
  const a4raw = $('A4 Gap Analyzer (short-circuit)').first().json.output;
  gaps = pj(a4raw) || { parse_error: 'A4 output was not valid JSON', raw: String(a4raw || '').slice(0, 4000) };
}
return [{ json: {
  branch: full ? 'full' : 'short',
  test: tc,
  run_id: ei.run_id,
  prompt_version: ei.prompt_version,
  input_type: c2.input_type,
  route: c2.route,
  status: c4.status,
  extraction: c4.extraction,
  c4_flags: c4.flags || [],
  approved_requirements: approved,
  prd: prd,
  compliance: compliance,
  epics: epics,
  stories: stories,
  gaps: gaps,
  estimates: est,
  timings: { started: Number(ei.eval_started_at), a1_done: Number(c4.a1_done_at) || null, a3_done: a3Done, end: Date.now() }
} }];

const r = $json;
const tc = r.test || {};
const HEAD = 'You are an impartial evaluator for PRD Genie, an AI assistant that turns meeting inputs into requirements, PRDs and user stories. INPUT: {{input}}\nSYSTEM OUTPUT: {{output}}\nEXPECTED (ground truth): {{expected_output}}\nTASK: ';
const TAIL = '\nReturn JSON only: {"score": <0.0-1.0>, "reasoning": "<one or two sentences naming what was missing or invented>"}. Do not reward length. Judge only against the INPUT and EXPECTED; do not use outside knowledge.';
const TASKS = {"M1": "List every item in EXPECTED 'must contain' (requirements, constraints, stakeholders, deadlines, dependencies, acceptance criteria). For each, check it is present in SYSTEM OUTPUT with the same meaning; numbers, units and versions must match exactly (e.g. '200ms' not '0.2s', '10,000' not '10K+'). Score = items present / items expected. Any rounded or altered number counts as missing.", "M2": "Check (a) input_status matches EXPECTED (INSUFFICIENT when no requirement is stated), (b) every ambiguous item and contradiction in EXPECTED is flagged, (c) no specific requirement was invented for vague input. Score = correct checks / total checks; if (c) fails, score = 0.", "M3": "Enumerate every requirement, NFR, acceptance criterion, persona, date and dependency in the PRD (SYSTEM OUTPUT). For each, decide if it is traceable to the INPUT (approved requirements). Score = traceable items / total items. Template guidance text and 'Not stated in source' placeholders are not counted as items.", "M5": "For each story, check: 'As a [user], I want [capability], so that [benefit]' form; a priority of Must Have, Should Have or Nice to Have. Then check each persona named in EXPECTED has its own stories (not merged into a generic 'user'). Score = compliant stories / total stories, multiplied by (personas covered / personas expected).", "M6": "For each acceptance criterion attached to a story, check it traces to a criterion stated in the INPUT. Any criterion that adds a condition not stated is 'added'. Score = faithful criteria / total criteria; if any criterion is added, score = min(score, 0.5).", "M7": "For each clarification question, decide if it targets a gap actually evidenced in the INPUT (cites or clearly refers to it) or is generic (could apply to any project). Score = specific questions / total questions.", "M8": "List every missing item, contradiction and risk in EXPECTED. Check whether the SYSTEM OUTPUT surfaces each (as a gap, question, contradiction or risk). Score = surfaced / expected.", "M9": "For each story, compare the underspecified flag with EXPECTED. A story is underspecified when information needed to build or size it is missing in the INPUT (e.g. unknown dependency ETA, undefined term). Score = correct flags / stories."};
const NAMES = { M1: 'm1_extraction_completeness', M2: 'm2_ambiguity_flag_accuracy', M3: 'm3_groundedness', M4: 'm4_format_compliance', M5: 'm5_story_format_persona', M6: 'm6_ac_fidelity', M7: 'm7_gap_relevance', M8: 'm8_gap_recall', M9: 'm9_underspecified_flag' };
const AGENT = { M1: 'A1', M2: 'A1', M3: 'A2', M4: 'A2', M5: 'A3', M6: 'A3', M7: 'A4', M8: 'A4', M9: 'A5' };
const full = r.branch === 'full';
const MAX = 30000;
function s(v) { const t = typeof v === 'string' ? v : JSON.stringify(v === undefined ? null : v); return t.length > MAX ? t.slice(0, MAX) + ' ...[truncated]' : t; }

// Which metrics to score: those listed for the test, plus M3/M4 on every full run (per metric definitions)
const jobs = [];
function add(m, expected, mustNot, extra) { if (NAMES[m] && !jobs.some(function (j) { return j.metric === m; })) jobs.push({ metric: m, expected: expected, must_not: mustNot, listed: !extra }); }
(String(tc.metrics || '').match(/\bM\d+\b/g) || []).forEach(function (m) { add(m, tc.expected_output, tc.must_not); });
// T11 and T12 are chained from T1: score them on T1's PRD and stories
if (String(tc.test_id) === 'T1') {
  ['M3', 'M4'].forEach(function (m) { add(m, 'Follows template structure (10 sections). All sections present. Only T1 requirements.', 'Requirements not in T1.'); });
  ['M5', 'M6', 'M9'].forEach(function (m) { add(m, "Epics and User Stories in 'As a [user]' format with priority suggestions.", 'Stories for requirements not in T11.'); });
}
if (full) { add('M3', tc.expected_output, tc.must_not); add('M4', tc.expected_output, tc.must_not); }
if (!jobs.some(function (j) { return j.metric === 'M1' || j.metric === 'M2'; })) add('M2', tc.expected_output, tc.must_not, true);
// Diagnostic coverage: score every agent that ran (not counted toward pass/fail)
if (full) { ['M5', 'M6', 'M7', 'M9'].forEach(function (m) { add(m, tc.expected_output, tc.must_not, true); }); }
else { ['M7', 'M8'].forEach(function (m) { add(m, tc.expected_output, tc.must_not, true); }); }

const source = String(tc.input_text || '');
const fixed = [];
const items = [];
jobs.forEach(function (j) {
  const needsFull = ['M3', 'M4', 'M5', 'M6', 'M9'].indexOf(j.metric) !== -1;
  if (needsFull && !full) { fixed.push({ metric: j.metric, listed: j.listed, score: 0, reason: 'Stage not reached: input was short-circuited at C3, so ' + AGENT[j.metric] + ' never ran.' }); return; }
  if (j.metric === 'M4') {
    const c = r.compliance || {};
    const missing = (c.missing_sections || []).length;
    let v = (10 - missing) / 10;
    if (c.in_order === false) v -= 0.1;
    if ((c.rows_without_source || []).length) v -= 0.1;
    if (c.parse_error) v = 0;
    v = Math.max(0, Math.min(1, Math.round(v * 100) / 100));
    fixed.push({ metric: 'M4', listed: j.listed, score: v, reason: 'C6 check: missing sections [' + (c.missing_sections || []).join(', ') + '], in order=' + c.in_order + ', rows without source=' + (c.rows_without_source || []).length + (c.parse_error ? ', ' + c.parse_error : '') });
    return;
  }
  let input = source; let output = '';
  if (j.metric === 'M1' || j.metric === 'M2') output = s(r.extraction);
  else if (j.metric === 'M3') { input = 'APPROVED REQUIREMENTS: ' + s(r.approved_requirements) + '\nSOURCE TEXT: ' + source; output = s(r.prd); }
  else if (j.metric === 'M5') { input = 'PRD: ' + s(r.prd); output = s({ epics: r.epics, stories: r.stories }); }
  else if (j.metric === 'M6') { input = 'PRD ACCEPTANCE CRITERIA: ' + s((r.prd || {})['Acceptance Criteria']) + '\nSOURCE TEXT: ' + source; output = s((r.stories || []).map(function (x) { return { story_id: x.story_id, story: x.story, acceptance_criteria: x.acceptance_criteria }; })); }
  else if (j.metric === 'M7' || j.metric === 'M8') output = s(r.gaps);
  else if (j.metric === 'M9') { input = 'STORIES: ' + s(r.stories) + '\nSOURCE TEXT: ' + source; output = s(r.estimates); }
  const prompt = (HEAD + TASKS[j.metric] + TAIL)
    .split('{{input}}').join(input)
    .split('{{output}}').join(output)
    .split('{{expected_output}}').join(String(j.expected || '') + '\nMUST NOT: ' + String(j.must_not || ''));
  items.push({ metric: j.metric, score_name: NAMES[j.metric], agent: AGENT[j.metric], listed: j.listed, prompt: prompt });
});

const summary = [
  'status=' + r.status,
  'requirements=' + (((r.extraction || {}).stated_requirements) || []).length,
  'prd=' + (r.prd ? 'yes' : 'no'),
  'stories=' + (r.stories || []).length,
  'gaps=' + (((r.gaps || {}).gaps) || []).length,
  'estimates=' + (((r.estimates || {}).estimates) || []).length
].join('; ');
const ctx = {
  test_id: tc.test_id, category: tc.category, negative_case: tc.negative_case, expected_route: tc.expected_route,
  run_id: r.run_id, prompt_version: r.prompt_version, branch: r.branch, status: r.status, input_type: r.input_type,
  route: r.route, timings: r.timings, fixed: fixed, summary: summary, listed: jobs.filter(function (j) { return j.listed; }).map(function (j) { return j.metric; })
};
return items.map(function (it) { return { json: Object.assign({}, it, { ctx: ctx }) }; });

const prompts = $('Build Judge Prompts').all();
const judged = $('LLM Judge').all();
const ctx = prompts[0].json.ctx;
const scores = {}; const reasons = {};
(ctx.fixed || []).forEach(function (f) { scores[f.metric] = f.score; reasons[f.metric] = f.reason; });
judged.forEach(function (it, i) {
  const p = prompts[i] ? prompts[i].json : null;
  if (!p) return;
  let v = 0; let why = 'judge output could not be parsed';
  try {
    const t = String(it.json.text || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
    const o = JSON.parse(t);
    v = Number(o.score); if (isNaN(v)) v = 0;
    v = Math.max(0, Math.min(1, v));
    why = String(o.reasoning || '');
  } catch (e) {}
  scores[p.metric] = v; reasons[p.metric] = why;
});

// Routing accuracy (C2 router + C3 gate) vs expected route
const exp = String(ctx.expected_route || '');
const expectShort = /short-circuit/i.test(exp);
const expectVC = /version comparison/i.test(exp);
const actualShort = ctx.branch === 'short';
const typeMatch = exp.match(/\/\s*(transcript|brief|notes)\b/i);
const typeOk = !typeMatch || String(ctx.input_type || '').toLowerCase() === typeMatch[1].toLowerCase();
const routing = (!expectVC && expectShort === actualShort && typeOk && ctx.route === 'main') ? 1 : 0;

// Pass thresholds from the metric definitions
const id = String(ctx.test_id);
function threshold(m) {
  if (m === 'M1') return ['T1', 'T4', 'T7'].indexOf(id) !== -1 ? 1 : 0.9;
  if (m === 'M7' || m === 'M9') return 0.8;
  if (m === 'M8') return ['T2', 'T3', 'T5', 'T10'].indexOf(id) !== -1 ? 1 : 0.9;
  return 1;
}
const failed = [];
const listed = ctx.listed || [];
Object.keys(scores).forEach(function (m) { if (listed.indexOf(m) !== -1 && scores[m] < threshold(m)) failed.push(m + '=' + scores[m] + ' (needs ' + threshold(m) + ')'); });
if (routing !== 1) failed.push('routing (expected "' + exp + '", got ' + (actualShort ? 'short-circuit' : 'full PRD pipeline') + ', input_type=' + ctx.input_type + ')');

function avg(list) { const v = list.filter(function (m) { return typeof scores[m] === 'number'; }).map(function (m) { return scores[m]; }); return v.length ? Math.round(v.reduce(function (a, b) { return a + b; }, 0) / v.length * 1000) / 1000 : null; }
const allVals = Object.keys(scores).filter(function (m) { return listed.indexOf(m) !== -1; }).map(function (m) { return scores[m]; });
const metricAvg = allVals.length ? Math.round(allVals.reduce(function (a, b) { return a + b; }, 0) / allVals.length * 1000) / 1000 : 0;
const hallucination = (typeof scores.M3 === 'number' && scores.M3 < 1 && ctx.branch === 'full') || (typeof scores.M6 === 'number' && scores.M6 <= 0.5 && ctx.branch === 'full') || (typeof scores.M2 === 'number' && scores.M2 === 0);
const t = ctx.timings || {};
function secs(a, b) { return (a && b) ? Math.round((b - a) / 100) / 10 : null; }
function g(m) { return typeof scores[m] === 'number' ? scores[m] : null; }
